import json
import re
from collections import Counter

# Constants
REPLACE_NONE = "None"

def task_func(json_str):
    """
    Process a JSON string by:
    1. Removing None values
    2. Counting the frequency of each unique value
    3. Replacing all email addresses with the placeholder "None"

    Args:
        json_str (str): A JSON string to process

    Returns:
        dict: A dictionary containing:
            "data": Processed JSON data
            "value_counts": A Counter object with the frequency of each unique value
    """
    # Parse the JSON string
    data = json.loads(json_str)

    # Email pattern for detection
    email_pattern = r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'

    def process_value(value):
        """Recursively process a value, removing None and replacing emails"""
        if value is None:
            return None  # Will be removed later

        if isinstance(value, str):
            # Replace email addresses with placeholder
            if re.match(email_pattern, value):
                return REPLACE_NONE
            return value

        if isinstance(value, dict):
            # Process dictionary - remove None values
            processed = {}
            for k, v in value.items():
                processed_v = process_value(v)
                if processed_v is not None:
                    processed[k] = processed_v
            return processed if processed else None

        if isinstance(value, list):
            # Process list - remove None values
            processed = []
            for item in value:
                processed_item = process_value(item)
                if processed_item is not None:
                    processed.append(processed_item)
            return processed if processed else None

        # For other types (int, float, bool), return as is
        return value

    def collect_values(value, counter):
        """Recursively collect all values for counting"""
        if value is None:
            return

        if isinstance(value, (str, int, float, bool)):
            counter[value] += 1
        elif isinstance(value, dict):
            for v in value.values():
                collect_values(v, counter)
        elif isinstance(value, list):
            for item in value:
                collect_values(item, counter)

    # Process the data
    processed_data = process_value(data)

    # Count frequencies
    value_counter = Counter()
    collect_values(processed_data, value_counter)

    return {
        "data": processed_data,
        "value_counts": value_counter
    }

